class RecentProduct {
  private nums: number[] = [];

  add(num: number): void {
    this.nums.push(num);
  }

  getProduct(k: number): number {
    let p = 1;
    for (let i = this.nums.length - k; i < this.nums.length; i++) p *= this.nums[i];
    return p;
  }
}

