class RecentProduct {
  private pre: number[] = [1];

  add(num: number): void {
    if (num === 0) this.pre = [1];
    else this.pre.push(this.pre[this.pre.length - 1] * num);
  }

  getProduct(k: number): number {
    const m = this.pre.length - 1;
    if (k > m) return 0; // the window includes the last zero
    return this.pre[m] / this.pre[m - k];
  }
}

